using Newtonsoft.Json.Linq;

namespace E33ModEditor.Core.Loot;

/// <summary>
/// The *condition* layer behind the weapon-passive archetypes: which build an
/// effect belongs to and which conditions are mutually exclusive. The archetype
/// table (<see cref="WeaponEffectArchetypes"/>) groups effects by theme; this
/// table stops a weapon holding two effects whose conditions fight, e.g.
/// Full Strength ("on full Health") next to Self Burn.
///
/// Stock lives in <c>Loot/Data/weapon_effect_conditions.json</c> (generated by
/// <c>Planning/archetypes/build_conditions.py</c>); the <c>work/</c> overlay wins
/// when present, same pattern as tiers / characters / archetypes. An effect with
/// no tags is neutral and never conflicts.
/// </summary>
public sealed class WeaponEffectConditions
{
    private readonly Dictionary<string, List<string>> _tags = new(StringComparer.Ordinal);
    private readonly HashSet<(string A, string B)> _conflicts = new();
    private readonly HashSet<string> _conflictTags = new(StringComparer.Ordinal);
    private readonly Dictionary<string, string> _element = new(StringComparer.Ordinal);
    private readonly List<(string When, IReadOnlyList<string> Prefer, IReadOnlyList<string> Avoid, int Weight)> _synergies = new();
    private string _raw = "{\"tags\":{}}";

    public bool ElementGateEnabled { get; private set; } = true;

    /// <summary>Every tag that participates in a conflict.</summary>
    public IReadOnlyList<string> ConditionTags =>
        _conflictTags.OrderBy(x => x, StringComparer.Ordinal).ToList();

    public IReadOnlyList<string> TagsOf(string? id) =>
        !string.IsNullOrEmpty(id) && _tags.TryGetValue(id, out var t)
            ? t : Array.Empty<string>();

    /// <summary>True when the effect carries no conflicting build condition.
    /// Informational tags (multi-hit, first-hit) do not count.</summary>
    public bool IsNeutral(string? id) => !TagsOf(id).Any(_conflictTags.Contains);

    private static readonly string[] StainGenerators =
    {
        "stain-gen-any", "stain-gen-fire", "stain-gen-ice", "stain-gen-lightning",
        "stain-gen-earth", "stain-gen-dark", "stain-gen-light", "stain-gen-lightdark",
        "stain-echo", "stain-convert",
    };

    /// <summary>
    /// Tags that make an effect a payoff rather than a standalone passive, and
    /// the tags that can enable it on the same weapon. Used only for the early
    /// T1–T3 roll restriction; a payoff is still legal later when a picto or
    /// another party member supplies the status.
    /// </summary>
    private static readonly Dictionary<string, string[]> RequiresEnabler =
        new(StringComparer.Ordinal)
        {
            ["shell-need"] = new[] { "shell-gen" },
            ["buff-conditional"] = new[] { "buff-apply" },
            ["burn-scale"] = new[] { "burn-apply" },
            ["burn-consume"] = new[] { "burn-apply" },
            ["shield-payoff"] = new[] { "shield-gen" },
            ["shield-spend"] = new[] { "shield-gen" },
            ["charge-consume"] = new[] { "charge-gen" },
            ["mark-payoff"] = new[] { "mark-apply" },
            ["perfection-payoff"] = new[] { "perfection-gain" },
            ["foretell-consume"] = new[] { "foretell-apply" },
            ["twilight-payoff"] = new[] { "twilight-enter" },
            ["sun-payoff"] = new[] { "charge-gen" },
            ["moon-payoff"] = new[] { "charge-gen" },
            ["consume-stain"] = StainGenerators,
            ["stain-scale"] = StainGenerators,
        };

    /// <summary>
    /// A standalone effect: no conflicting condition and no build payoff that
    /// needs a status/stain/shield engine. This is what the T3+ bad-luck floor
    /// puts on every guaranteed weapon.
    /// </summary>
    public bool IsUnconditional(string? id) =>
        IsNeutral(id) && !TagsOf(id).Any(t => RequiresEnabler.ContainsKey(t));

    /// <summary>
    /// True when every payoff tag on <paramref name="id"/> has its enabler
    /// either on the same effect or already committed to the weapon. Effects
    /// with no payoff tags always pass.
    /// </summary>
    public bool EnablerSatisfied(string? id, IReadOnlySet<string> pickedTags)
    {
        var tags = TagsOf(id);
        foreach (var t in tags)
        {
            if (!RequiresEnabler.TryGetValue(t, out var enablers)) continue;
            if (!enablers.Any(e => tags.Contains(e) || pickedTags.Contains(e)))
                return false;
        }
        return true;
    }

    /// <summary>Stain/melee element for gated effects, else null.</summary>
    public string? ElementOf(string? id) =>
        !string.IsNullOrEmpty(id) && _element.TryGetValue(id, out var e) ? e : null;

    /// <summary>Effect id → element for the element-gated families.</summary>
    public IReadOnlyDictionary<string, string> ElementEffects => _element;

    /// <summary>
    /// True when adding <paramref name="id"/> would put two conflicting
    /// conditions on one weapon.
    /// </summary>
    public bool Conflicts(IReadOnlySet<string> pickedTags, string? id)
    {
        if (pickedTags.Count == 0) return false;
        foreach (var t in TagsOf(id))
            foreach (var p in pickedTags)
                if (_conflicts.Contains(Key(t, p)))
                    return true;
        return false;
    }

    public IReadOnlyList<(string When, IReadOnlyList<string> Prefer, IReadOnlyList<string> Avoid, int Weight)> Synergies => _synergies;

    /// <summary>
    /// Net synergy draw weight for <paramref name="id"/> given what is already
    /// on the weapon. Uses the *strongest* active trigger (max), not a sum, so
    /// a weight-4 engine pull is not diluted by several weight-2 preferences:
    /// return (max prefer weight) − (max avoid weight).
    /// </summary>
    public int SynergyWeight(string? id, IReadOnlySet<string> pickedTags)
    {
        if (_synergies.Count == 0 || pickedTags.Count == 0) return 0;
        var tags = TagsOf(id);
        if (tags.Count == 0) return 0;
        var best = 0;
        var worst = 0;
        foreach (var (when, prefer, avoid, weight) in _synergies)
        {
            if (!pickedTags.Contains(when)) continue;
            if (weight > best && prefer.Any(t => tags.Contains(t, StringComparer.Ordinal))) best = weight;
            if (weight > worst && avoid.Any(t => tags.Contains(t, StringComparer.Ordinal))) worst = weight;
        }
        return best - worst;
    }

    /// <summary>True when the effect's own tag set is internally consistent.</summary>
    public bool SelfConsistent(string? id)
    {
        var tags = TagsOf(id);
        for (int i = 0; i < tags.Count; i++)
            for (int j = i + 1; j < tags.Count; j++)
                if (_conflicts.Contains(Key(tags[i], tags[j])))
                    return false;
        return true;
    }

    public static string OverlayPath =>
        Path.Combine(EditorPaths.RepoRoot, "work", "weapon_effect_conditions.json");

    public static string StockSourcePath =>
        Path.Combine(EditorPaths.RepoRoot, "src", "E33ModEditor.Core", "Loot", "Data",
            "weapon_effect_conditions.json");

    public static WeaponEffectConditions Load()
    {
        var c = new WeaponEffectConditions();
        c.ResetToStock();
        if (File.Exists(OverlayPath))
        {
            try { c.ReplaceFromJson(File.ReadAllText(OverlayPath)); }
            catch { /* keep stock */ }
        }
        return c;
    }

    public void ResetToStock() => ReplaceFromJson(ReadStock());

    public void ReplaceFromJson(string json)
    {
        var root = JObject.Parse(json);
        var tags = new Dictionary<string, List<string>>(StringComparer.Ordinal);
        foreach (var (id, arr) in (root["tags"] as JObject ?? new JObject())
                     .Properties().Select(p => (p.Name, p.Value as JArray)))
        {
            if (arr is null) continue;
            var list = arr.Select(x => (string?)x ?? "")
                .Where(x => x.Length > 0)
                .Distinct(StringComparer.Ordinal)
                .ToList();
            if (list.Count > 0) tags[id] = list;
        }

        var conflicts = new HashSet<(string, string)>();
        foreach (var pair in root["conflicts"] as JArray ?? new JArray())
        {
            if (pair is not JArray { Count: >= 2 }) continue;
            var a = (string?)pair[0] ?? "";
            var b = (string?)pair[1] ?? "";
            if (a.Length == 0 || b.Length == 0) continue;
            conflicts.Add(Key(a, b));
        }

        var conflictTags = new HashSet<string>(StringComparer.Ordinal);
        foreach (var t in root["conflictTags"] as JArray ?? new JArray())
        {
            var s = (string?)t ?? "";
            if (s.Length > 0) conflictTags.Add(s);
        }
        // Fallback for older files: anything named in a conflict is a conflict tag.
        foreach (var (a, b) in conflicts) { conflictTags.Add(a); conflictTags.Add(b); }

        var synergies = new List<(string When, IReadOnlyList<string> Prefer, IReadOnlyList<string> Avoid, int Weight)>();
        foreach (var s in root["synergies"] as JArray ?? new JArray())
        {
            var when = (string?)s["when"] ?? "";
            var weight = (int?)s["weight"] ?? 1;
            var prefer = (s["prefer"] as JArray)?
                .Select(x => (string?)x ?? "")
                .Where(x => x.Length > 0).ToList() ?? new List<string>();
            var avoid = (s["avoid"] as JArray)?
                .Select(x => (string?)x ?? "")
                .Where(x => x.Length > 0).ToList() ?? new List<string>();
            if (when.Length > 0 && (prefer.Count > 0 || avoid.Count > 0))
                synergies.Add((when, prefer, avoid, Math.Max(1, weight)));
        }

        var element = new Dictionary<string, string>(StringComparer.Ordinal);
        foreach (var p in ((root["elementGate"]?["elements"]) as JObject ?? new JObject()).Properties())
        {
            var el = (string?)p.Value ?? "";
            if (el.Length > 0) element[p.Name] = el;
        }
        var gateEnabled = (bool?)(root["elementGate"]?["enabled"]) ?? true;

        _tags.Clear();
        foreach (var (k, v) in tags) _tags[k] = v;
        _conflicts.Clear();
        foreach (var c in conflicts) _conflicts.Add(c);
        _conflictTags.Clear();
        foreach (var t in conflictTags) _conflictTags.Add(t);
        _element.Clear();
        foreach (var (k, v) in element) _element[k] = v;
        _synergies.Clear();
        foreach (var (when, prefer, avoid, weight) in synergies)
            _synergies.Add((when, prefer, avoid, weight));
        ElementGateEnabled = gateEnabled;
        _raw = json;
    }

    public string ToJson() => _raw;

    public void Save()
    {
        var json = ToJson();
        Directory.CreateDirectory(Path.GetDirectoryName(OverlayPath)!);
        File.WriteAllText(OverlayPath, json);
        try
        {
            var dir = Path.GetDirectoryName(StockSourcePath);
            if (!string.IsNullOrEmpty(dir) && Directory.Exists(dir))
                File.WriteAllText(StockSourcePath, json);
        }
        catch { /* packed install */ }
    }

    private static (string A, string B) Key(string a, string b) =>
        string.CompareOrdinal(a, b) <= 0 ? (a, b) : (b, a);

    private static string ReadStock()
    {
        var asm = typeof(WeaponEffectConditions).Assembly;
        var name = asm.GetManifestResourceNames()
            .First(n => n.EndsWith("weapon_effect_conditions.json", StringComparison.OrdinalIgnoreCase));
        using var s = asm.GetManifestResourceStream(name)!;
        using var r = new StreamReader(s);
        return r.ReadToEnd();
    }
}
